        if(head == null)return null;
        if(k==1){
            head = head.next;
            return head;
        }
        ListNode temp = head;
        while(temp != null && temp.next != null){
            if(k==2){
                temp.next = temp.next.next;
                break;
            }
            temp = temp.next;
            k--;
        }
        return head;
    }
